1	package blueprint
2	
3	import (
4		"bytes"
5		"encoding/json"
6		"fmt"
7		"io"
8		"os"
9		"strings"
10		"text/template"
11	
12		"github.com/Masterminds/sprig/v3"
13		"github.com/santhosh-tekuri/jsonschema/v5"
14		"gopkg.in/yaml.v3"
15	)
16	
17	// StdinValuesPath is the sentinel a caller may pass in the values-file list
18	// to signal "read a single values document from this reader". It mirrors the
19	// `-f -` idiom used by helm, kubectl, and curl.
20	const StdinValuesPath = "-"
21	
22	// Resolve produces the final value map by layering, in order:
23	//
24	//	defaults declared in spec.parameters.properties[*].default
25	//	--values files (in supplied order; "-" reads one doc from stdin)
26	//	--set flags (string values, coerced to declared JSON Schema types)
27	//	prompts for required parameters still missing (when prompter != nil)
28	//
29	// stdin is consumed at most once across the files list; passing "-" twice is
30	// an error. The merged map is then validated against the JSON Schema in
31	// spec.parameters. Finally, every entry in spec.values is rendered as a Go
32	// text/template (with sprig) against the merged map and added under its key.
33	// A spec.values key that collides with a parameter name is rejected.
34	func Resolve(t *Template, files []string, stdin io.Reader, sets map[string]any, prompter Prompter) (map[string]any, error) {
35		fields := t.Fields()
36		byName := indexFields(fields)
37		out := map[string]any{}
38	
39		applyDefaultValues(fields, out)
40		if err := applyValuesFiles(files, stdin, out, byName); err != nil {
41			return nil, err
42		}
43		applySetValues(sets, out, byName)
44		if err := promptForMissingRequired(fields, out, prompter); err != nil {
45			return nil, err
46		}
47		if err := validateSchema(t.Spec.Parameters, out); err != nil {
48			return nil, fmt.Errorf("parameter validation: %w", err)
49		}
50		if err := renderDerivedValues(t.Spec.Values, out, byName); err != nil {
51			return nil, err
52		}
53	
54		return out, nil
55	}
56	
57	func applyDefaultValues(fields []FieldSpec, values map[string]any) {
58		for _, f := range fields {
59			if f.Default != nil {
60				values[f.Name] = f.Default
61			}
62		}
63	}
64	
65	func applyValuesFiles(files []string, stdin io.Reader, values map[string]any, byName map[string]FieldSpec) error {
66		stdinUsed := false
67		for _, path := range files {
68			if path == StdinValuesPath {
69				if stdinUsed {
70					return fmt.Errorf("--values - specified more than once (stdin can only be read once)")
71				}
72				if stdin == nil {
73					return fmt.Errorf("--values - specified but no stdin reader provided")
74				}
75				data, err := io.ReadAll(stdin)
76				if err != nil {
77					return fmt.Errorf("read values from stdin: %w", err)
78				}
79				if err := mergeValuesBytes(data, "stdin", values, byName); err != nil {
80					return err
81				}
82				stdinUsed = true
83				continue
84			}
85			if err := mergeValuesFile(path, values, byName); err != nil {
86				return err
87			}
88		}
89		return nil
90	}
91	
92	func applySetValues(sets map[string]any, values map[string]any, byName map[string]FieldSpec) {
93		for k, v := range sets {
94			values[k] = coerceKnownFieldValue(k, v, byName)
95		}
96	}
97	
98	func promptForMissingRequired(fields []FieldSpec, values map[string]any, prompter Prompter) error {
99		missing := missingRequired(fields, values)
100		if len(missing) == 0 {
101			return nil
102		}
103		if prompter == nil {
104			names := make([]string, 0, len(missing))
105			for _, f := range missing {
106				names = append(names, f.Name)
107			}
108			return fmt.Errorf("missing required parameter(s): %s", strings.Join(names, ", "))
109		}
110		for _, f := range missing {
111			ans, err := prompter.Prompt(f)
112			if err != nil {
113				return err
114			}
115			if isEmpty(ans) {
116				return fmt.Errorf("required parameter %q has no value", f.Name)
117			}
118			values[f.Name] = ans
119		}
120		return nil
121	}
122	
123	func renderDerivedValues(derived map[string]string, values map[string]any, byName map[string]FieldSpec) error {
124		for k, expr := range derived {
125			if _, collides := byName[k]; collides {
126				return fmt.Errorf("spec.values.%s collides with a parameter of the same name", k)
127			}
128			rendered, err := renderExpr(expr, values)
129			if err != nil {
130				return fmt.Errorf("spec.values.%s: %w", k, err)
131			}
132			values[k] = rendered
133		}
134		return nil
135	}
136	
137	func mergeValuesFile(path string, into map[string]any, byName map[string]FieldSpec) error {
138		data, err := os.ReadFile(path)
139		if err != nil {
140			return fmt.Errorf("read values file %s: %w", path, err)
141		}
142		return mergeValuesBytes(data, path, into, byName)
143	}
144	
145	func mergeValuesBytes(data []byte, source string, into map[string]any, byName map[string]FieldSpec) error {
146		var fileVals map[string]any
147		if err := yaml.Unmarshal(data, &fileVals); err != nil {
148			return fmt.Errorf("parse values from %s: %w", source, err)
149		}
150		for k, v := range fileVals {
151			into[k] = coerceKnownFieldValue(k, v, byName)
152		}
153		return nil
154	}
155	
156	func coerceKnownFieldValue(name string, value any, byName map[string]FieldSpec) any {
157		field, ok := byName[name]
158		if !ok {
159			return value
160		}
161		str, ok := value.(string)
162		if !ok {
163			return value
164		}
165		return coerce(str, field.Type)
166	}
167	
168	func indexFields(fields []FieldSpec) map[string]FieldSpec {
169		m := make(map[string]FieldSpec, len(fields))
170		for _, f := range fields {
171			m[f.Name] = f
172		}
173		return m
174	}
175	
176	func missingRequired(fields []FieldSpec, values map[string]any) []FieldSpec {
177		var missing []FieldSpec
178		for _, f := range fields {
179			if !f.Required {
180				continue
181			}
182			if v, ok := values[f.Name]; ok && !isEmpty(v) {
183				continue
184			}
185			missing = append(missing, f)
186		}
187		return missing
188	}
189	
190	func validateSchema(schema map[string]any, values map[string]any) error {
191		raw, err := json.Marshal(schema)
192		if err != nil {
193			return err
194		}
195		c := jsonschema.NewCompiler()
196		if err := c.AddResource("inline://params.json", bytes.NewReader(raw)); err != nil {
197			return err
198		}
199		s, err := c.Compile("inline://params.json")
200		if err != nil {
201			return err
202		}
203		return s.Validate(values)
204	}
205	
206	// renderExpr renders a Go text/template string (with sprig) against the
207	// supplied data map. Used for spec.values entries.
208	func renderExpr(expr string, data map[string]any) (string, error) {
209		tmpl, err := template.New("expr").
210			Funcs(sprig.TxtFuncMap()).
211			Option("missingkey=error").
212			Parse(expr)
213		if err != nil {
214			return "", err
215		}
216		var sb strings.Builder
217		if err := tmpl.Execute(&sb, data); err != nil {
218			return "", err
219		}
220		return sb.String(), nil
221	}
222	
223	// ParseSets converts ["key=value", ...] into a map. Values stay as strings;
224	// Resolve coerces them to the JSON Schema type when the key matches a known
225	// parameter.
226	func ParseSets(items []string) (map[string]any, error) {
227		out := map[string]any{}
228		for _, item := range items {
229			i := strings.Index(item, "=")
230			if i <= 0 {
231				return nil, fmt.Errorf("invalid --set %q (expected key=value)", item)
232			}
233			out[item[:i]] = item[i+1:]
234		}
235		return out, nil
236	}
237	
238	func isEmpty(v any) bool {
239		switch t := v.(type) {
240		case nil:
241			return true
242		case string:
243			return t == ""
244		default:
245			return false
246		}
247	}
